<template>
  <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-4">
    <AppSearchInputQuery :query="params.search || null" property-name="search" placeholder="Search imports..." />
    <AppComboboxQuery
      :value="`${params.sort_by}|${params.sort_type}`"
      :items="importsSortBy"
      property-name="sort_by|sort_type"
      :null-is-all="false"
      placeholder="Sorting"
      empty-text="No sorting options"
      :clearable="false"
      :icon="ArrowUpDownIcon"
    />
    <AppMultiComboboxQuery
      :value="params.project_ids || null"
      :items="projectItems"
      property-name="project_ids"
      :null-is-all="true"
      placeholder="All projects"
      items-plural-name="projects"
      input-placeholder="Search project..."
      empty-text="No projects found"
      :loading="isLoadingProjects"
      :icon="FilterIcon"
    />
    <AppMultiComboboxQuery
      :value="params.statuses || null"
      :items="importStatusFilterItems"
      property-name="statuses"
      :null-is-all="true"
      placeholder="All statuses"
      items-plural-name="statuses"
      empty-text="No statuses found"
      :icon="FilterIcon"
    />
    <AppMultiComboboxQuery
      :value="params.target_providers || null"
      :items="providerItems"
      property-name="target_providers"
      :null-is-all="true"
      placeholder="All providers"
      items-plural-name="providers"
      empty-text="No providers found"
      :loading="isLoadingProviders"
      :icon="FilterIcon"
    />
    <AppRangeDatePickerQuery
      :value="{ start: params.created_at_from || null, end: params.created_at_to || null }"
      :property-names="{ start: 'created_at_from', end: 'created_at_to' }"
      :clear-button="Boolean(params.created_at_from || params.created_at_to)"
    />
  </div>
</template>

<script setup lang="ts">
import { ArrowUpDownIcon, FilterIcon } from 'lucide-vue-next';
import type { ListCanvassingInteractionImportsData, CanvassingApplicationName } from '~/client';
import { importStatusFilterItems } from '~/constants/canvassing-interaction-imports/importStatusFilterItems';
import { importsSortBy } from '~/constants/canvassing-interaction-imports/importsSortBy';
import { getProjectCanvassingAppLabel } from '~/constants/projects/projectCanvassingAppLabel';

defineProps<{
  params: NonNullable<ListCanvassingInteractionImportsData['query']>;
}>();

const { projects, isLoading: isLoadingProjects } = useSelectorProjectList();
const { canvassingApps, isLoading: isLoadingProviders } = useSelectorCanvassingAppList();

const projectItems = computed<SelectItem<string>[]>(() =>
  (projects.value ?? []).map((p) => ({ name: p.name, value: p.id }))
);

const providerItems = computed<SelectItem<CanvassingApplicationName>[]>(() =>
  (canvassingApps.value ?? []).map((app) => {
    const value = app.value as CanvassingApplicationName;
    return {
      name: getProjectCanvassingAppLabel(value),
      value,
    };
  })
);
</script>
