<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Canvassing Interaction Imports">
      <Button data-testid="imports-list-upload-btn" @click="uploadOpen = true">Upload CSV</Button>
    </PageTitle>

    <ImportsListFilters :params="params" />

    <ImportsList
      :items="data?.items ?? []"
      :total-count="data?.total_count ?? 0"
      :page="params.page"
      :size="params.size"
      :is-loading="isLoading"
      :error="error"
      :guided-content="guidedContent"
      :show-guided="showGuided"
      @upload="uploadOpen = true"
    />

    <UploadModal v-model="uploadOpen" @uploaded="onUploaded" />
  </section>
</template>

<script setup lang="ts">
import {
  listCanvassingInteractionImports,
  type ListCanvassingInteractionImportsData,
  type ListCanvassingInteractionImportsResponse,
  type CanvassingInteractionImportSortBy,
  type CanvassingInteractionImportStatus,
  type CanvassingApplicationName,
  type SortType,
} from '~/client';
import { canvassingImportsGuidedEmpty } from '~/constants/guidedEmpty/canvassingImports';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'imports',
});

useHead({
  title: 'Canvassing Interaction Imports',
});

const route = useRoute('canvassing-interaction-imports');
const router = useRouter();

const uploadOpen = ref(false);

function parseArray<T extends string>(raw: unknown): T[] | undefined {
  if (raw == null) return undefined;
  const arr = Array.isArray(raw) ? raw : [raw];
  const clean = arr.filter((v): v is string => typeof v === 'string' && v.length > 0) as T[];
  return clean.length ? clean : undefined;
}

const { timezone } = useUserRole();

const params = computed((): NonNullable<ListCanvassingInteractionImportsData['query']> => {
  const { page, size } = parsePagination(route.query, { size: 25 });
  return {
    page,
    size,
    sort_type: (route.query.sort_type as SortType) || 'desc',
    sort_by: ((route.query.sort_by as CanvassingInteractionImportSortBy) ||
      'created_at') as CanvassingInteractionImportSortBy,
    search: (route.query.search as string) || undefined,
    project_ids: parseArray<string>(route.query.project_ids),
    statuses: parseArray<CanvassingInteractionImportStatus>(route.query.statuses),
    target_providers: parseArray<CanvassingApplicationName>(route.query.target_providers),
    created_at_from: (route.query.created_at_from as string) || undefined,
    created_at_to: (route.query.created_at_to as string) || undefined,
    timezone: timezone.value || undefined,
  };
});

const { data, error, isLoading } = useQuery({
  key: () => ['canvassing-interaction-imports.list', params.value],
  query: (): Promise<ListCanvassingInteractionImportsResponse> =>
    listCanvassingInteractionImports({ composable: '$fetch', query: ref(params.value) }),
  staleTime: 0,
});

const isEmpty = computed(() => !data.value || data.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(canvassingImportsGuidedEmpty, isEmpty);

async function onUploaded(importId: string) {
  await router.push({
    name: 'canvassing-interaction-imports-importId',
    params: { importId },
  });
}
</script>
