<template>
  <Card>
    <AppLoader v-if="isLoading" subject="canvassing interaction imports" variant="inline" />
    <AppError v-else-if="error" :error="error" title="Failed to load canvassing interaction imports" variant="table" />
    <ResponsiveTable v-else rounded>
      <ResponsiveTableHeader>
        <ResponsiveTableHead>
          <button
            type="button"
            class="inline-flex items-center gap-1 hover:underline"
            data-testid="imports-list-sort-name"
            @click="onSort('name')"
          >
            Name
            <ArrowUpDownIcon v-if="sortBy !== 'name'" class="size-3 opacity-50" />
            <ArrowUpIcon v-else-if="sortType === 'asc'" class="size-3" />
            <ArrowDownIcon v-else class="size-3" />
          </button>
        </ResponsiveTableHead>
        <ResponsiveTableHead>Project</ResponsiveTableHead>
        <ResponsiveTableHead>Uploaded By</ResponsiveTableHead>
        <ResponsiveTableHead>Provider</ResponsiveTableHead>
        <ResponsiveTableHead>
          <button
            type="button"
            class="inline-flex items-center gap-1 hover:underline"
            data-testid="imports-list-sort-status"
            @click="onSort('status')"
          >
            Status
            <ArrowUpDownIcon v-if="sortBy !== 'status'" class="size-3 opacity-50" />
            <ArrowUpIcon v-else-if="sortType === 'asc'" class="size-3" />
            <ArrowDownIcon v-else class="size-3" />
          </button>
        </ResponsiveTableHead>
        <ResponsiveTableHead class="text-nowrap">Total</ResponsiveTableHead>
        <ResponsiveTableHead class="text-nowrap">
          <button
            type="button"
            class="inline-flex items-center gap-1 hover:underline"
            data-testid="imports-list-sort-created-at"
            @click="onSort('created_at')"
          >
            Created At
            <ArrowUpDownIcon v-if="sortBy !== 'created_at'" class="size-3 opacity-50" />
            <ArrowUpIcon v-else-if="sortType === 'asc'" class="size-3" />
            <ArrowDownIcon v-else class="size-3" />
          </button>
        </ResponsiveTableHead>
      </ResponsiveTableHeader>
      <ResponsiveTableBody>
        <ResponsiveTableEmpty
          v-if="!items || items.length === 0"
          :colspan="7"
          :cols="4"
          :cols-sm="4"
          class="text-center"
        >
          <AppGuidedEmpty
            v-if="showGuided && guidedContent"
            v-bind="guidedContent"
            variant="table"
            @action="(event) => event === 'upload' && emit('upload')"
          />
          <AppEmpty v-else variant="table" subject="canvassing interaction imports" />
        </ResponsiveTableEmpty>
        <ResponsiveTableRow
          v-for="item in items"
          :key="item.id"
          :to="{ name: 'canvassing-interaction-imports-importId', params: { importId: item.id } }"
          :data-testid="`imports-list-row-${item.id}`"
        >
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Name" class="font-medium">
            {{ item.name }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Project">
            {{ item.project.name }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Uploaded By">
            {{ username(item.created_by_user) }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Provider">
            {{ providerLabel(item.target_provider) }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Status">
            <Badge :variant="getImportStatus(item.status).variant" size="sm">
              {{ getImportStatus(item.status).label }}
            </Badge>
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Total">
            {{ item.all_rows_count }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="4" :cols-sm="4" label="Created At" class="text-nowrap">
            {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
          </ResponsiveTableCell>
        </ResponsiveTableRow>
      </ResponsiveTableBody>
      <ResponsiveTableFooter v-if="!error && !isLoading && totalCount > 0" :colspan="7" :cols="2" :cols-sm="2">
        <AppPagination :page="page" :total="totalCount" :size="size" label="imports" />
      </ResponsiveTableFooter>
    </ResponsiveTable>
  </Card>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { ArrowUpDownIcon, ArrowUpIcon, ArrowDownIcon } from 'lucide-vue-next';
import type {
  CanvassingInteractionImportListItemResponse,
  CanvassingInteractionImportSortBy,
  CanvassingApplicationName,
  SortType,
} from '~/client';
import { getImportStatus } from '~/constants/canvassing-interaction-imports/importStatusConfig';
import { getProjectCanvassingAppLabel } from '~/constants/projects/projectCanvassingAppLabel';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { username } from '~/utils/username';

defineProps<{
  items: CanvassingInteractionImportListItemResponse[];
  totalCount: number;
  page: number;
  size: number;
  isLoading: boolean;
  error: Error | null;
  guidedContent?: GuidedEmptyContent | null;
  showGuided?: boolean;
}>();

const emit = defineEmits<{ upload: [] }>();

const { timezone: timezoneRef } = useUserRole();
const timezone = computed(() => timezoneRef.value);

const route = useRoute();
const sortBy = computed(() => (route.query.sort_by as CanvassingInteractionImportSortBy) || 'created_at');
const sortType = computed(() => (route.query.sort_type as SortType) || 'desc');

function providerLabel(provider: CanvassingApplicationName): string {
  return getProjectCanvassingAppLabel(provider);
}

async function onSort(column: CanvassingInteractionImportSortBy) {
  const nextType: SortType = sortBy.value === column ? (sortType.value === 'asc' ? 'desc' : 'asc') : 'desc';
  await navigateTo({
    name: route.name,
    params: route.params,
    query: { ...route.query, page: 1, sort_by: column, sort_type: nextType },
  });
}
</script>
